// BRAND DEAL OUTREACH ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows and is generated from one file, so the
// sender and the reply handler can never disagree about which inbox belongs to which
// student, or about what counts as a booked deal.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what lets
// this be demonstrated on a screen-share before a single credential exists.

// ---------------------------------------------------------------- Airtable: the database
// The student dashboard the brief describes. Blank = the run uses the built-in demo roster
// and writes nothing.
//   API key:  airtable.com/create/tokens (a PAT with data.records:read and :write)
//   Base id:  the "app..." segment of the base's URL
const AIRTABLE_API_KEY = '';
const AIRTABLE_BASE_ID = '';
const AIRTABLE_URL     = 'https://api.airtable.com/v0';

const STUDENTS_TABLE = 'Students';   // one row per creator we send for
const BRANDS_TABLE   = 'Brands';     // the target list, per niche
const PITCHES_TABLE  = 'Pitches';    // one row per pitch. Written same day, always.
const INBOXES_TABLE  = 'Inboxes';    // sending accounts and their health

// Field names, exactly as they appear in Airtable.
const STUDENT_FIELDS = {
  student_id:   'Student id',
  name:         'Name',
  handle:       'Handle',
  niche:        'Niche',
  platform:     'Platform',
  followers:    'Followers',
  avg_views:    'Average views',
  rate_card:    'Rate card',
  min_rate:     'Minimum rate',
  deliverables: 'Deliverables',
  proof:        'Proof points',
  status:       'Status',
  started_on:   'Engagement start',
  monthly_target: 'Monthly pitch target'
};

const BRAND_FIELDS = {
  brand_id:     'Brand id',
  brand:        'Brand',
  niche:        'Niche',
  contact_name: 'Contact name',
  contact_email: 'Contact email',
  role:         'Role',
  budget_band:  'Budget band',
  recent_signal: 'Recent signal',
  product:      'Product',
  region:       'Region',
  status:       'Status'
};

const PITCH_FIELDS = {
  pitch_id:    'Pitch id',
  student_id:  'Student id',
  student:     'Student',
  brand_id:    'Brand id',
  brand:       'Brand',
  contact:     'Contact',
  email:       'Email',
  inbox:       'Sent from',
  subject:     'Subject',
  body:        'Body',
  facts_used:  'Facts used',
  sent_at:     'Sent at',
  state:       'State',
  hold_reason: 'Hold reason',
  reply_at:    'Replied at',
  reply_class: 'Reply',
  booked_at:   'Booked at',
  deal_value:  'Deal value'
};

const INBOX_FIELDS = {
  inbox_id:     'Inbox id',
  email:        'Email',
  domain:       'Domain',
  student_id:   'Student id',
  warmed_days:  'Days warming',
  daily_cap:    'Daily cap',
  sent_today:   'Sent today',
  bounce_rate:  'Bounce rate',
  spam_rate:    'Spam complaint rate',
  health_score: 'Health score',
  state:        'State'
};

// Only students in these states are pitched for.
const ACTIVE_STUDENT_STATES = ['Active', 'Onboarding complete', ''];
// Only brands in these states are pitched. Anything else has been contacted or ruled out.
const OPEN_BRAND_STATES = ['New', 'Researched', ''];

// ---------------------------------------------------------------- Volume
// The brief's number is 10,000+ pitches a month across all students. That is a per-student
// daily figure once you divide it by working days, and it is the figure that has to be
// enforced — a month's target is not a thing you can rate-limit against.
const PITCHES_PER_STUDENT_PER_DAY = 25;
const DAILY_CAP                   = 400;  // hard ceiling across all students, per run
const MAX_PER_BRAND_PER_STUDENT   = 1;    // never pitch the same brand twice for one creator
const REPITCH_AFTER_DAYS          = 90;   // a brand that said no is left alone this long

// ---------------------------------------------------------------- Deliverability
// The second of their three hard gates. This is the part that fails CLOSED: an inbox that
// cannot be proved healthy does not send. Every other mistake in cold outreach is
// recoverable; a burnt sending domain is not, and it takes the student's name with it.
const MIN_WARMUP_DAYS   = 14;    // an inbox younger than this sends nothing
const MAX_BOUNCE_RATE   = 0.03;  // 3% — above this the inbox is pulled from rotation
const MAX_SPAM_RATE     = 0.001; // 0.1%
const MIN_HEALTH_SCORE  = 70;    // whatever your sending platform reports, 0-100
const MAX_PER_INBOX_DAY = 40;    // per mailbox, not per domain
const MAX_PER_DOMAIN_DAY = 120;  // across every mailbox on one domain

// An inbox whose health the platform will not tell us about. true = do not send from it.
// Leave it true: an unknown inbox is not a healthy one.
const HOLD_UNKNOWN_INBOX = true;

// ---------------------------------------------------------------- Personalisation
// Their third hard gate: "pitches read human and personal from line one. Never templated."
//
// A pitch must carry at least MIN_FACTS specific, verifiable details drawn from the BRAND
// and STUDENT records — not from the model. If the record does not contain enough to say
// something true and specific, the pitch is HELD, not sent with a generic line in its place.
// That is the difference between personalisation and mail-merge, and it is checkable.
const MIN_FACTS = 3;

// And at least this many of them about the BRAND. Creator numbers are facts too, but a
// pitch made only of them is a CV — MIN_FACTS alone would let one through on the strength
// of the follower count.
const MIN_BRAND_FACTS = 2;

// Which brand record fields count as a usable fact. A blank field is not a fact.
//
// `budget_band` is deliberately NOT here. It is real, and it gates the match upstream, and
// it must never appear in an email — telling a company what you think their budget is, is
// the single fastest way to lose the deal you were quoting into.
const FACT_FIELDS = ['recent_signal', 'product', 'role'];

// Phrases that give a template away. A pitch containing any of these is held and rewritten.
// This list is the single most useful thing in this config — add to it every time you read
// a sent pitch and wince.
const BANNED_PHRASES = [
  'i hope this email finds you well', 'i hope this finds you well', 'quick question',
  'just following up', 'circling back', 'touching base', 'i wanted to reach out',
  'i came across your', 'i stumbled upon', 'love what you are doing',
  'love what you’re doing', 'we are a leading', 'synergy', 'game-changing',
  'revolutionary', 'to whom it may concern', 'dear sir or madam', 'per my last email',
  'as per', 'kindly revert', 'i am reaching out to you today'
];

// A pitch outside this range is held. Short enough to read on a phone, long enough to say
// something.
const MIN_WORDS = 60;
const MAX_WORDS = 160;

// Never send to these. Domains or full addresses. Anything that replies "remove me" is
// added here by workflow 02.
const SUPPRESSION = [];

// Role mailboxes nobody owns. Held — these are where bounce rates come from.
const ROLE_PREFIXES = ['info', 'hello', 'contact', 'support', 'admin', 'sales', 'help',
  'noreply', 'no-reply', 'press', 'careers', 'jobs', 'legal', 'billing', 'webmaster'];

// ---------------------------------------------------------------- The writer
// The model rewrites the SUBJECT and the OPENING LINE around facts that were assembled in
// code. It is never handed the rate card and asked to improvise a number.
// Blank = the skeleton pitch is produced and held for a human to finish. Nothing is sent
// unwritten.
const AI_API_KEY = '';
const AI_URL     = 'https://api.anthropic.com/v1/messages';
const AI_MODEL   = 'claude-opus-5';

// ---------------------------------------------------------------- The sending engine
// Instantly by default. Smartlead works the same way: change SEND_URL and the body built in
// "payload for the campaign".
const SEND_API_KEY  = '';
const SEND_URL      = 'https://api.instantly.ai/api/v2/leads';
const REPLIES_URL   = 'https://api.instantly.ai/api/v2/emails';
const CAMPAIGN_ID   = '';

// Optional: a different campaign per niche, so a skincare brand and a gaming brand are not
// sent the same sequence. Anything not listed here goes to CAMPAIGN_ID.
const CAMPAIGN_BY_NICHE = {
  // 'Beauty': 'campaign-uuid-here',
  // 'Gaming': 'campaign-uuid-here'
};

// ---------------------------------------------------------------- Replies (workflow 02)
// How a reply is classified. First rule whose words appear wins, so put the specific ones
// first. Anything that matches nothing is 'unclear' and goes to a human — never guessed.
const REPLY_RULES = [
  { klass: 'unsubscribe', route: 'suppress',
    words: ['unsubscribe', 'remove me', 'take me off', 'do not contact', 'opt out',
            'stop emailing'] },
  { klass: 'auto-reply', route: 'ignore',
    words: ['out of office', 'automatic reply', 'auto-reply', 'annual leave',
            'on holiday', 'currently away', 'parental leave'] },
  { klass: 'bounce', route: 'suppress',
    words: ['undeliverable', 'delivery failed', 'address not found', 'mailbox full',
            'recipient rejected', 'does not exist'] },
  { klass: 'wrong-person', route: 'reroute',
    words: ['no longer with', 'has left', 'not the right person', 'forward this to',
            'my colleague handles', 'wrong department'] },
  { klass: 'not-now', route: 'nurture',
    words: ['next quarter', 'next year', 'budget is set', 'revisit', 'not right now',
            'circle back in', 'check back'] },
  { klass: 'not-interested', route: 'close',
    words: ['not interested', 'no thanks', 'we will pass', 'we’ll pass', 'not a fit',
            'not for us', 'declining'] },
  { klass: 'interested', route: 'handover',
    words: ['interested', 'tell me more', 'send over', 'rates', 'media kit', 'happy to chat',
            'set up a call', 'what would', 'pricing', 'sounds good', 'let’s talk'] }
];

// A reply routed 'handover' is a human's job — the brief pays a person to work the replies,
// and this workflow's job is to put the right ones in front of them fast, not to negotiate.
const HANDOVER_WEBHOOK_URL = '';   // Slack channel for interested replies. Blank = summary only.

// ---------------------------------------------------------------- Weekly report
// "Report weekly — clean numbers so students and the team can see progress."
// Runs on the hourly trigger, on this day and hour only.
const REPORT_DAY  = 1;   // 0 Sunday … 6 Saturday
const REPORT_HOUR = 9;   // 24h, in the n8n instance's timezone
const REPORT_WINDOW_DAYS = 7;

const ALERT_WEBHOOK_URL = '';   // Slack incoming webhook for the run summaries.

// ---------------------------------------------------------------- Demo mode
// With no Airtable key set, builds a deterministic roster — six students, sixty brands,
// four inboxes with a realistic spread of health — so the whole engine can be watched end
// to end before an account exists. While this is on the run is FORCED into preview: a
// fabricated brand contact can never be emailed.
const DEMO_ROSTER = true;

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_EMAIL blank -> PREVIEW. Every pitch is written, audited and
//                                       assigned an inbox, and NOTHING is sent or logged.
//                                       Ships this way.
//   TEST_RUN true,  TEST_EMAIL set   -> TEST. Pitches really are sent, all redirected to
//                                       that address, so you can read what a brand would get.
//   TEST_RUN false                   -> LIVE.
const TEST_RUN   = true;
const TEST_EMAIL = '';

const DEMO_DATA = DEMO_ROSTER === true && AIRTABLE_API_KEY.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

// A fabricated brand contact is not a lead. It cannot open the send gate, whatever
// TEST_RUN says.
const FORCED_PREVIEW = DEMO_DATA && MODE !== 'preview';
if (FORCED_PREVIEW) MODE = 'preview';

const now = new Date();
const REPORT_DUE = now.getDay() === Number(REPORT_DAY) &&
                   now.getHours() === Number(REPORT_HOUR);

return [{
  json: {
    airtable_url:  AIRTABLE_URL,
    airtable_key:  AIRTABLE_API_KEY.trim(),
    airtable_base: AIRTABLE_BASE_ID.trim(),
    students_table: STUDENTS_TABLE,
    brands_table:   BRANDS_TABLE,
    pitches_table:  PITCHES_TABLE,
    inboxes_table:  INBOXES_TABLE,
    student_fields: STUDENT_FIELDS,
    brand_fields:   BRAND_FIELDS,
    pitch_fields:   PITCH_FIELDS,
    inbox_fields:   INBOX_FIELDS,
    active_student_states: ACTIVE_STUDENT_STATES,
    open_brand_states:     OPEN_BRAND_STATES,

    pitches_per_student_per_day: Number(PITCHES_PER_STUDENT_PER_DAY) || 25,
    daily_cap:                   Number(DAILY_CAP) || 0,
    max_per_brand_per_student:   Number(MAX_PER_BRAND_PER_STUDENT) || 1,
    repitch_after_days:          Number(REPITCH_AFTER_DAYS) || 90,

    min_warmup_days:    Number(MIN_WARMUP_DAYS) || 0,
    max_bounce_rate:    Number(MAX_BOUNCE_RATE) || 0,
    max_spam_rate:      Number(MAX_SPAM_RATE) || 0,
    min_health_score:   Number(MIN_HEALTH_SCORE) || 0,
    max_per_inbox_day:  Number(MAX_PER_INBOX_DAY) || 0,
    max_per_domain_day: Number(MAX_PER_DOMAIN_DAY) || 0,
    hold_unknown_inbox: HOLD_UNKNOWN_INBOX !== false,

    min_facts:       Number(MIN_FACTS) || 0,
    min_brand_facts: Number(MIN_BRAND_FACTS) || 0,
    fact_fields: FACT_FIELDS,
    banned_phrases: BANNED_PHRASES.map(function (p) { return String(p).toLowerCase(); }),
    min_words:   Number(MIN_WORDS) || 0,
    max_words:   Number(MAX_WORDS) || 9999,
    suppression: SUPPRESSION.map(function (s) { return String(s).trim().toLowerCase(); })
      .filter(Boolean),
    role_prefixes: ROLE_PREFIXES,

    ai_api_key: AI_API_KEY.trim(),
    ai_url:     AI_URL,
    ai_model:   AI_MODEL,

    send_api_key: SEND_API_KEY.trim(),
    send_url:     SEND_URL,
    replies_url:  REPLIES_URL,
    campaign_id:  CAMPAIGN_ID.trim(),
    campaign_by_niche: CAMPAIGN_BY_NICHE,

    reply_rules: REPLY_RULES,
    handover_webhook_url: HANDOVER_WEBHOOK_URL.trim(),

    report_day:  Number(REPORT_DAY),
    report_hour: Number(REPORT_HOUR),
    report_window_days: Number(REPORT_WINDOW_DAYS) || 7,
    alert_webhook_url:  ALERT_WEBHOOK_URL.trim(),
    test_email: TEST_EMAIL.trim(),

    // derived flags — the gates read these, never the raw constants
    mode:         MODE,
    preview_only: MODE === 'preview',
    test_send:    MODE === 'test',
    live_send:    MODE === 'live',

    airtable_enabled: AIRTABLE_API_KEY.trim() !== '' && AIRTABLE_BASE_ID.trim() !== '',
    log_enabled:      MODE !== 'preview' && AIRTABLE_API_KEY.trim() !== ''
                      && AIRTABLE_BASE_ID.trim() !== '',
    ai_enabled:       AI_API_KEY.trim() !== '',
    send_enabled:     MODE !== 'preview' && SEND_API_KEY.trim() !== '' &&
                      CAMPAIGN_ID.trim() !== '',
    replies_enabled:  SEND_API_KEY.trim() !== '',
    alert_enabled:    ALERT_WEBHOOK_URL.trim() !== '',
    handover_enabled: (HANDOVER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim()) !== '',
    handover_url:     HANDOVER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim(),
    report_due:       REPORT_DUE,
    demo_data:        DEMO_DATA,
    forced_preview:   FORCED_PREVIEW
  }
}];

// Normalises the sending platform's reply feed into one item shaped {replies}.
//
// Instantly's v2 GET /emails returns sent and received mail together. Only inbound is a
// reply, and only inbound from the last window is a NEW reply — re-classifying yesterday's
// is how a brand gets handed over twice and a person emails them twice.
const cfg = $('config').first().json;
const resp = $('[cred] Instantly - fetch replies').first().json || {};

const failures = [];
let rows = [];
if (resp.error || (!Array.isArray(resp.items) && !Array.isArray(resp.data))) {
  failures.push('replies: ' + ((resp.error && (resp.error.message || resp.error)) ||
    'no response'));
} else {
  rows = Array.isArray(resp.items) ? resp.items : resp.data;
}

if (failures.length) {
  throw new Error('The reply feed returned nothing usable (' + failures.join('; ') +
    '). Refusing to report a quiet inbox — a reply nobody reads is the one thing this ' +
    'workflow exists to prevent.');
}

const replies = rows.filter(function (m) {
  const dir = String(m.email_type || m.direction || '').toLowerCase();
  return dir === 'received' || dir === 'inbound' || m.is_reply === true;
}).map(function (m) {
  const vars = m.lead_data || m.custom_variables || {};
  return {
    reply_id: m.id || m.message_id || '',
    pitch_id: vars.pitch_id || '',
    from_name: m.from_name || vars.first_name || '',
    from: m.from_address_email || m.from || '',
    brand: vars.company_name || m.company_name || '',
    student: vars.creator || '',
    subject: m.subject || '',
    text: String(m.body_text || m.body || m.content || '').slice(0, 4000),
    received_at: m.timestamp_created || m.date || new Date().toISOString(),
    inbox: m.eaccount || m.to_address_email || ''
  };
});

return [{
  json: {
    source: 'instantly',
    read_at: new Date().toISOString(),
    failures: failures,
    replies: replies
  }
}];

// STOP: no sending platform configured — build a demo reply batch instead.
//
// Deterministic, and deliberately awkward: one reply of every class the rules know about,
// plus two that match nothing. Those last two are the important ones. A classifier
// demonstrated only on replies it can classify is a classifier nobody has tested.
const cfg = $('config').first().json;

if (cfg.replies_enabled) {
  throw new Error('demo replies reached with a sending key configured — check the IF gate');
}

const DAY = 86400000;
const now = Date.now();
function iso(ms) { return new Date(ms).toISOString(); }

const REPLIES = [
  ['P-ST-01-BR-001-20260902', 'Sofie Brandt', 'sofie.brandt@kestrelliving.example',
   'Kestrel Living', 'Nadia Osei',
   'Re: the modular sofa line',
   'This is interesting — can you send over rates and the last two campaigns she ran? ' +
   'Happy to jump on a call next week.'],
  ['P-ST-02-BR-011-20260902', 'Elena Ruiz', 'elena.ruiz@copperpotsauces.example',
   'Copper Pot Sauces', 'Tomas Ferreira',
   'Re: Tesco listing',
   'Thanks but we are not interested at the moment, our influencer budget is committed ' +
   'through the autumn.'],
  ['P-ST-03-BR-026-20260902', 'Beth Okoye', 'beth.okoye@rowansupplements.example',
   'Rowan Supplements', 'Priya Raman',
   'Re: the reformulated protein line',
   'Please unsubscribe me from this list and do not contact me again.'],
  ['P-ST-04-BR-031-20260902', 'Marc Dubois', 'marc.dubois@hexlineperipherals.example',
   'Hexline Peripherals', 'Leo Hartmann',
   'Automatic reply: Re: the wireless mouse',
   'I am out of office until the 14th with limited access to email.'],
  ['P-ST-05-BR-041-20260902', 'Aisha Rahman', 'aisha.rahman@lumenskin.example',
   'Lumen Skin', 'Amara Chike',
   'Re: fragrance-free serum',
   'I have left Lumen — please forward this to Dan who now handles partnerships.'],
  ['P-ST-06-BR-051-20260902', 'Mei Tanaka', 'mei.tanaka@paperfoldstudio.example',
   'Paperfold Studio', 'Iris Vandermeer',
   'Re: the watercolour set',
   'Budget is set for this year. Worth revisiting in January if she is still available.'],
  ['P-ST-01-BR-002-20260902', 'postmaster', 'postmaster@northwoodceramics.example',
   'Northwood Ceramics', 'Nadia Osei',
   'Undeliverable: Partnership with Nadia Osei',
   'Your message could not be delivered. The address was not found at this domain.'],
  // Matches nothing. Goes to a human, is never guessed at.
  ['P-ST-02-BR-012-20260902', 'Tom Aldridge', 'tom.aldridge@grainhousebakery.example',
   'Grainhouse Bakery', 'Tomas Ferreira',
   'Re: shipping nationwide',
   'Who is this for exactly? We had someone else email us about the same thing yesterday.'],
  ['P-ST-04-BR-032-20260902', 'Sara Lindholm', 'sara.lindholm@nightfallstudios.example',
   'Nightfall Studios', 'Leo Hartmann',
   'Re: early access',
   'Depends entirely on the numbers.']
];

return [{
  json: {
    source: 'demo',
    read_at: new Date().toISOString(),
    failures: [],
    replies: REPLIES.map(function (r, i) {
      return { reply_id: 'R-' + (1000 + i), pitch_id: r[0], from_name: r[1], from: r[2],
        brand: r[3], student: r[4], subject: r[5], text: r[6],
        received_at: iso(now - (i + 1) * 3600000),
        inbox: 'outreach@northbeam-outreach.example' };
    }),
    _note: 'DEMO REPLIES — nine fabricated replies, two of which match no rule on purpose.'
  }
}];

// One item per reply, with a class and a route.
//
// The rules are ordered and the FIRST match wins, which is why `unsubscribe` and `bounce`
// sit above `interested`. "Please remove me, though the numbers were interesting" is an
// unsubscribe, and getting that precedence wrong is a complaint, not a missed deal.
//
// A reply that matches nothing is `unclear`, routed to a human, and never guessed at. The
// brief pays a person to work the replies; this workflow's job is to put the right ones in
// front of them fast, not to negotiate on their behalf.
const cfg = $('config').first().json;
const feed = $json;

const replies = feed.replies || [];
if (!replies.length) {
  return [{
    json: { _has_replies: false, source: feed.source, read_at: feed.read_at,
      headline: 'No new replies in this window.' }
  }];
}

function classify(text) {
  const t = String(text || '').toLowerCase();
  for (let i = 0; i < cfg.reply_rules.length; i++) {
    const rule = cfg.reply_rules[i];
    for (let w = 0; w < rule.words.length; w++) {
      if (t.indexOf(String(rule.words[w]).toLowerCase()) !== -1) {
        return { klass: rule.klass, route: rule.route, matched: rule.words[w] };
      }
    }
  }
  return { klass: 'unclear', route: 'handover', matched: '' };
}

const counts = {};
const out = replies.map(function (r) {
  const verdict = classify(r.subject + ' ' + r.text);
  counts[verdict.klass] = (counts[verdict.klass] || 0) + 1;
  return {
    json: Object.assign({}, r, {
      _has_replies: true,
      reply_class: verdict.klass,
      route: verdict.route,
      matched_on: verdict.matched,
      // An unclear reply is not a low-priority one. It is the one most likely to be a deal
      // nobody recognised, so it goes to a person with the same urgency as an obvious yes.
      urgent: verdict.route === 'handover',
      source: feed.source
    })
  };
});

out.forEach(function (o) { o.json._counts = counts; });
return out;

// STOP: no new replies in this window.
//
// The common case, on an hourly trigger. It still produces a summary item so the run has a
// shape the summary node understands — and so a silent hour and a broken feed do not look
// the same from the outside. A feed that errors throws upstream in 'read the replies'
// rather than arriving here as a quiet hour.
const j = $json;

return [{
  json: {
    _has_replies: false,
    source: j.source,
    read_at: j.read_at,
    headline: j.headline || 'No new replies in this window.',
    recorded_at: new Date().toISOString()
  }
}];

// What happens to each reply, decided in one place.
//
// Five routes, and only one of them involves a person:
//
//   handover   interested, or unclear -> a human, now. This is the money.
//   suppress   unsubscribe or hard bounce -> added to the suppression list, and the pitch
//              row is closed. Nothing about this is optional or delayed.
//   reroute    wrong person -> the pitch is closed and the brand goes back to the target
//              list for research, because the company is still a fit even though the
//              contact is not.
//   nurture    not now, with a date attached -> closed, re-pitchable after the window.
//   close      not interested -> closed.
//   ignore     auto-reply -> nothing at all. An out-of-office is not a reply and must not
//              consume the follow-up.
const cfg = $('config').first().json;
const items = $input.all();

const DAY = 86400000;
const now = Date.now();

const ACTIONS = {
  handover: { state: 'Replied — with a human', close: false, suppress: false },
  suppress: { state: 'Closed — suppressed', close: true, suppress: true },
  reroute:  { state: 'Closed — wrong contact', close: true, suppress: false },
  nurture:  { state: 'Closed — revisit', close: true, suppress: false },
  close:    { state: 'Closed — not interested', close: true, suppress: false },
  ignore:   { state: '', close: false, suppress: false }
};

const suppressionAdds = [];
const handovers = [];

const out = items.map(function (item) {
  const r = item.json;
  const action = ACTIONS[r.route] || ACTIONS.handover;

  if (action.suppress && r.from) suppressionAdds.push(String(r.from).toLowerCase());
  if (r.route === 'handover') handovers.push(r);

  const revisitAfter = r.reply_class === 'not-now'
    ? new Date(now + Number(cfg.repitch_after_days || 90) * DAY).toISOString().slice(0, 10)
    : '';

  return {
    json: Object.assign({}, r, {
      action: r.route,
      new_state: action.state,
      closes_the_pitch: action.close,
      adds_to_suppression: action.suppress,
      revisit_after: revisitAfter,
      // An auto-reply changes nothing, and saying so explicitly is what stops somebody
      // "fixing" it later by counting it as engagement.
      writes_back: r.route !== 'ignore',
      next_step: r.route === 'handover'
        ? (r.reply_class === 'unclear'
          ? 'read it — the classifier could not place this one'
          : 'a person replies with rates and the media kit')
        : r.route === 'suppress' ? 'suppressed; nothing further is sent to this address'
        : r.route === 'reroute' ? 'back to the target list for a new contact'
        : r.route === 'nurture' ? 'revisit after ' + revisitAfter
        : r.route === 'close' ? 'closed'
        : 'no action — automatic reply'
    })
  };
});

out.forEach(function (o) {
  o.json._suppression_adds = suppressionAdds;
  o.json._handover_count = handovers.length;
});
return out;

// Updates the pitch rows these replies belong to, ten at a time.
//
// Airtable's PATCH /v0/{base}/{table} with `performUpsert.fieldsToMergeOn` matches on a
// field rather than a record id, which is what lets this run without having kept every
// record id from the day the pitch was sent. `Pitch id` is that field, and it is why the
// pitch id is deterministic — student, brand, date — rather than random.
//
// An auto-reply writes nothing. It is not a reply.
const cfg = $('config').first().json;
const F = cfg.pitch_fields;
const items = $input.all().filter(function (i) { return i.json.writes_back; });

const BATCH = 10;
const out = [];

for (let i = 0; i < items.length; i += BATCH) {
  const chunk = items.slice(i, i + BATCH).map(function (item) {
    const r = item.json;
    const row = {};
    row[F.pitch_id] = r.pitch_id;
    row[F.reply_at] = r.received_at;
    row[F.reply_class] = r.reply_class;
    row[F.state] = r.new_state;
    row[F.hold_reason] = r.next_step;
    return { fields: row };
  });
  out.push({
    json: {
      _batch: (i / BATCH) + 1,
      _count: chunk.length,
      _body: {
        records: chunk,
        typecast: true,
        performUpsert: { fieldsToMergeOn: [F.pitch_id] }
      }
    }
  });
}

if (!out.length) {
  return [{ json: { _batch: 0, _count: 0,
    _body: { records: [], typecast: true,
             performUpsert: { fieldsToMergeOn: [F.pitch_id] } } } }];
}
return out;

// Did every reply reach the dashboard? Same check as the sender's, same reason.
//
// Auto-replies are excluded from the expected count, because they are deliberately not
// written back. Counting them would manufacture a permanent, meaningless log gap and the
// alert would be ignored inside a week.
const replies = $('decide the next step').all().map(function (i) { return i.json; });
const expected = replies.filter(function (r) { return r.writes_back; }).length;
const responses = $input.all().map(function (i) { return i.json || {}; });

let written = 0;
const errors = [];
responses.forEach(function (r) {
  if (Array.isArray(r.records)) { written += r.records.length; return; }
  errors.push((r.error && (r.error.message || r.error.type || r.error)) ||
    'batch returned no records');
});

const gap = expected - written;

return replies.map(function (r) {
  return { json: Object.assign({}, r, {
    logged: gap === 0,
    log_gap: gap > 0,
    log_written: written,
    log_expected: expected,
    log_reason: gap === 0 ? '' :
      gap + ' of ' + expected + ' replies did not reach the dashboard' +
      (errors.length ? ' (' + errors.join('; ') + ')' : '')
  }) };
});

// STOP: the reply outcomes were not written back.
//
// Reportable, not quiet. In particular the suppressions did not land, which means the next
// run could email somebody who asked not to be emailed. That is the one failure in this
// engine with a legal edge on it, so it is named in the summary rather than counted.
const cfg = $('config').first().json;
const items = $input.all();
const suppressions = (items[0] && items[0].json._suppression_adds) || [];

return items.map(function (item) {
  return { json: Object.assign({}, item.json, {
    logged: false,
    log_gap: item.json.writes_back === true,
    log_reason: cfg.airtable_enabled
      ? 'logging is off in this mode'
      : 'Airtable is not configured — nothing was written back' +
        (suppressions.length
          ? ', including ' + suppressions.length + ' suppression(s) that must be added by hand'
          : '')
  }) };
});

// The hourly reply summary. Short, because it fires every hour and a long one stops being
// read by Tuesday.
const cfg = $('config').first().json;
const items = $input.all().map(function (i) { return i.json; });

const quiet = items.filter(function (j) { return j._has_replies === false; })[0];
const replies = items.filter(function (j) { return j._has_replies !== false && j.reply_id; });

const counts = (replies[0] && replies[0]._counts) || {};
const handovers = replies.filter(function (r) { return r.route === 'handover'; });
const unclear = replies.filter(function (r) { return r.reply_class === 'unclear'; });
const suppressions = (replies[0] && replies[0]._suppression_adds) || [];
const logGap = replies.filter(function (r) { return r.log_gap === true; }).length > 0;
const logReason = (replies.filter(function (r) { return r.log_reason; })[0] || {}).log_reason;

const lines = [];
if (quiet) {
  lines.push('*Replies* — ' + quiet.headline);
} else {
  lines.push('*Replies* — ' + replies.length + ' in this window');
  lines.push(Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a]; })
    .map(function (k) { return counts[k] + ' ' + k; }).join(' · '));
  if (handovers.length) {
    lines.push(':bell: ' + handovers.length + ' need a person now' +
      (unclear.length ? ' (' + unclear.length + ' the classifier could not place)' : ''));
  }
  if (suppressions.length) {
    lines.push(suppressions.length + ' added to suppression');
  }
  if (logGap) lines.push(':rotating_light: log gap — ' + logReason);
}

return [{
  json: {
    mode: cfg.mode,
    source: quiet ? quiet.source : (replies[0] && replies[0].source),
    replies: replies.length,
    counts: counts,
    handovers: handovers.map(function (r) {
      return { student: r.student, brand: r.brand, contact: r.from_name, from: r.from,
        klass: r.reply_class, subject: r.subject,
        excerpt: String(r.text || '').slice(0, 240), next_step: r.next_step };
    }),
    suppressions: suppressions,
    log_gap: logGap,
    log_reason: logReason || '',
    summary: lines.join('\n'),
    _has_handovers: handovers.length > 0,
    _alert_body: { text: lines.join('\n') }
  }
}];

// The message that actually earns the fee: an interested brand, in front of a person,
// within the hour, with enough context to reply without opening anything else.
//
// Deliberately separate from the hourly summary. A summary is scanned; a handover has to be
// acted on, and putting the two in one message means the second gets treated like the first.
const s = $json;

const lines = [];
lines.push('*' + s.handovers.length + ' repl' +
  (s.handovers.length === 1 ? 'y needs' : 'ies need') + ' a person*');
lines.push('');

s.handovers.slice(0, 10).forEach(function (h) {
  lines.push('*' + h.brand + '* → ' + h.student);
  lines.push('_' + h.contact + ' <' + h.from + '>_ · ' + h.klass);
  lines.push('> ' + String(h.excerpt).replace(/\n+/g, ' '));
  lines.push('→ ' + h.next_step);
  lines.push('');
});

if (s.handovers.length > 10) {
  lines.push('… and ' + (s.handovers.length - 10) + ' more in the dashboard.');
}

return [{ json: Object.assign({}, s, { _handover_body: { text: lines.join('\n') } }) }];

// Normalises the Airtable pitch log into the same {pitches} shape the demo log produces,
// so the report node never knows which one it got.
const cfg = $('config').first().json;
const F = cfg.pitch_fields;
const resp = $('[cred] Airtable - the pitch log').first().json || {};

if (resp.error || !Array.isArray(resp.records)) {
  throw new Error('The pitch log returned nothing usable (' +
    ((resp.error && (resp.error.message || resp.error)) || 'no response') +
    '). A weekly report built on a failed read would show a quiet week that did not happen.');
}

return [{
  json: {
    source: 'airtable',
    read_at: new Date().toISOString(),
    pitches: resp.records.map(function (r) {
      const f = r.fields || {};
      return {
        pitch_id:    f[F.pitch_id],
        student_id:  f[F.student_id],
        student:     f[F.student],
        brand:       f[F.brand],
        state:       f[F.state],
        hold_reason: f[F.hold_reason],
        sent_at:     f[F.sent_at],
        reply_at:    f[F.reply_at],
        reply_class: f[F.reply_class],
        booked_at:   f[F.booked_at],
        deal_value:  f[F.deal_value]
      };
    })
  }
}];

// STOP: no Airtable — fabricate a week of pitch log so the report is demonstrable.
//
// A week that looks like a real one: volume concentrated on weekdays, a reply rate in the
// low single digits, two booked deals, and a visible block of held pitches. The held block
// is the one worth pointing at on a call — it is what the audit and the deliverability gate
// cost you, and it is the number the client should be arguing about.
const cfg = $('config').first().json;

const DAY = 86400000;
const now = Date.now();
function iso(ms) { return new Date(ms).toISOString(); }

const STUDENTS = [
  ['ST-01', 'Nadia Osei'], ['ST-02', 'Tomas Ferreira'], ['ST-03', 'Priya Raman'],
  ['ST-04', 'Leo Hartmann'], ['ST-05', 'Amara Chike'], ['ST-06', 'Iris Vandermeer']
];
const HOLDS = [
  'only 2 usable facts, needs 3 — the brand record is too thin to say anything specific',
  'template tell: "i hope this email finds you well"',
  'role mailbox (info@) — nobody owns it, and it is where bounce rates come from',
  'every healthy inbox is at its daily ceiling — this rolls to the next run',
  'no fact about the brand itself — this reads as a CV, not as outreach'
];
const CLASSES = ['interested', 'not-interested', 'not-now', 'unsubscribe', 'auto-reply',
  'unclear'];

let seed = 20260908;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }

const records = [];
let n = 0;
for (let d = Number(cfg.report_window_days || 7) - 1; d >= 0; d--) {
  const at = now - d * DAY;
  const weekday = new Date(at).getDay();
  if (weekday === 0 || weekday === 6) continue;   // nobody pitches at the weekend

  STUDENTS.forEach(function (s) {
    const planned = Number(cfg.pitches_per_student_per_day || 25);
    for (let i = 0; i < planned; i++) {
      n++;
      const held = rnd() < 0.22;
      const replied = !held && rnd() < 0.06;
      const klass = replied ? CLASSES[Math.floor(rnd() * CLASSES.length)] : '';
      const booked = klass === 'interested' && rnd() < 0.35;
      records.push({
        pitch_id: 'P-' + s[0] + '-DEMO-' + n,
        student_id: s[0],
        student: s[1],
        brand: 'Demo brand ' + n,
        state: held ? 'held' : (klass ? 'Replied — with a human' : 'sent'),
        hold_reason: held ? HOLDS[n % HOLDS.length] : '',
        sent_at: held ? '' : iso(at),
        reply_at: replied ? iso(at + 6 * 3600000) : '',
        reply_class: klass,
        booked_at: booked ? iso(at + 2 * DAY) : '',
        deal_value: booked ? [800, 1200, 1500, 2200][n % 4] : ''
      });
    }
  });
}

return [{
  json: {
    source: 'demo',
    read_at: new Date().toISOString(),
    pitches: records,
    _note: 'DEMO PITCH LOG — ' + records.length + ' fabricated rows over the last ' +
           cfg.report_window_days + ' days.'
  }
}];

// "Report weekly — clean numbers so students and the team can see progress."
//
// One block per student, because that is how the engagement is sold: $50 per student per
// month, two months each. A student who cannot see their own numbers has no way to judge
// whether the two months were worth it, and that judgement is the renewal.
//
// Three rules run through it:
//
//   Held pitches are shown, not hidden. They are the cost of the quality gates, and a
//   client who cannot see that number cannot decide whether the gates are set right.
//
//   Rates are computed against what was SENT, never against what was written. A reply rate
//   that quietly divides by the bigger number flatters the run and is wrong.
//
//   A student below their pro-rata target is named. The point of a weekly report is to
//   catch that on the Monday, not at the end of the engagement.
const cfg = $('config').first().json;
const log = $json;

const DAY = 86400000;
const now = Date.now();
const windowStart = now - Number(cfg.report_window_days || 7) * DAY;

function stamp(s) {
  if (!s) return null;
  const ms = Date.parse(String(s));
  return isNaN(ms) ? null : ms;
}
function pct(a, b) { return b ? Math.round((a / b) * 1000) / 10 : 0; }

const rows = (log.pitches || []).filter(function (p) {
  const at = stamp(p.sent_at) || stamp(p.reply_at);
  return at === null ? String(p.state || '').toLowerCase() === 'held' : at >= windowStart;
});

const byStudent = {};
const holdReasons = {};

rows.forEach(function (p) {
  const k = p.student || p.student_id || 'unknown';
  if (!byStudent[k]) {
    byStudent[k] = { student: k, written: 0, sent: 0, held: 0, replies: 0, interested: 0,
      booked: 0, value: 0, unsubscribes: 0 };
  }
  const s = byStudent[k];
  s.written++;
  const held = String(p.state || '').toLowerCase() === 'held';
  if (held) {
    s.held++;
    const key = String(p.hold_reason || 'held').split(':')[0].split('—')[0].trim();
    holdReasons[key] = (holdReasons[key] || 0) + 1;
  } else if (p.sent_at) {
    s.sent++;
  }
  if (p.reply_class && p.reply_class !== 'auto-reply' && p.reply_class !== 'bounce') {
    s.replies++;
    if (p.reply_class === 'interested') s.interested++;
    if (p.reply_class === 'unsubscribe') s.unsubscribes++;
  }
  if (p.booked_at) { s.booked++; s.value += Number(p.deal_value || 0); }
});

const students = Object.keys(byStudent).map(function (k) {
  const s = byStudent[k];
  s.reply_rate = pct(s.replies, s.sent);
  s.interest_rate = pct(s.interested, s.sent);
  s.unsub_rate = pct(s.unsubscribes, s.sent);
  return s;
}).sort(function (a, b) { return b.sent - a.sent; });

const totals = students.reduce(function (a, s) {
  a.written += s.written; a.sent += s.sent; a.held += s.held; a.replies += s.replies;
  a.interested += s.interested; a.booked += s.booked; a.value += s.value;
  a.unsubscribes += s.unsubscribes;
  return a;
}, { written: 0, sent: 0, held: 0, replies: 0, interested: 0, booked: 0, value: 0,
     unsubscribes: 0 });

// Working days in the window, so the target is pro-rata rather than a monthly figure
// compared against a week.
let workingDays = 0;
for (let d = 0; d < Number(cfg.report_window_days || 7); d++) {
  const day = new Date(now - d * DAY).getDay();
  if (day !== 0 && day !== 6) workingDays++;
}
const targetPerStudent = Number(cfg.pitches_per_student_per_day || 25) * workingDays;
const behind = students.filter(function (s) { return s.sent < targetPerStudent * 0.8; });

const lines = [];
lines.push('*Weekly outreach report* — last ' + cfg.report_window_days + ' days (' +
  workingDays + ' working days)');
lines.push('');
lines.push('*Totals*');
lines.push('• ' + totals.sent + ' sent of ' + totals.written + ' written · ' +
  totals.held + ' held by the quality gates');
lines.push('• ' + totals.replies + ' replies (' + pct(totals.replies, totals.sent) +
  '%) · ' + totals.interested + ' interested (' + pct(totals.interested, totals.sent) + '%)');
lines.push('• ' + totals.booked + ' booked' +
  (totals.value ? ' · £' + totals.value.toLocaleString('en-GB') : ''));
lines.push('• ' + totals.unsubscribes + ' unsubscribes (' +
  pct(totals.unsubscribes, totals.sent) + '%)');
lines.push('');
lines.push('*By student* — target ' + targetPerStudent + ' sent each');
students.forEach(function (s) {
  lines.push('• *' + s.student + '* ' + s.sent + ' sent · ' + s.replies + ' replies (' +
    s.reply_rate + '%) · ' + s.interested + ' interested · ' + s.booked + ' booked' +
    (s.sent < targetPerStudent * 0.8 ? '  ⚠ behind target' : ''));
});

if (Object.keys(holdReasons).length) {
  lines.push('');
  lines.push('*Held because* — this is what the quality gates cost, and it is meant to be ' +
    'argued with');
  Object.keys(holdReasons).sort(function (a, b) { return holdReasons[b] - holdReasons[a]; })
    .slice(0, 6).forEach(function (k) {
      lines.push('• ' + holdReasons[k] + ' × ' + k);
    });
}

lines.push('');
lines.push('Source: ' + log.source + (log.source === 'demo'
  ? ' — fabricated log, no account connected' : ''));

return [{
  json: {
    window_days: Number(cfg.report_window_days || 7),
    working_days: workingDays,
    target_per_student: targetPerStudent,
    totals: totals,
    by_student: students,
    hold_reasons: holdReasons,
    behind: behind.map(function (s) { return s.student; }),
    source: log.source,
    report: lines.join('\n'),
    _report_body: { text: lines.join('\n') }
  }
}];
